public sealed class AppDbContext(DbContextOptions<AppDbContext> o, ITenantContext tenant)
    : DbContext(o)
{
    public DbSet<Invoice> Invoices => Set<Invoice>();

    protected override void OnModelCreating(ModelBuilder b) =>
        b.Entity<Invoice>().HasQueryFilter(i => i.TenantId == tenant.TenantId);
}

public static class OrdersEndpoints
{
    public static IEndpointRouteBuilder MapOrders(this IEndpointRouteBuilder app)
    {
        var g = app.MapGroup("/api/orders").WithTags("Orders").RequireAuthorization();
        g.MapGet("/{id:int}", GetById);
        g.MapPost("/", Create).AddEndpointFilter<ValidationFilter<CreateOrder>>();
        return app;
    }

    static async Task<Results<Ok<OrderDto>, NotFound>> GetById(int id, IOrderService s, CancellationToken ct)
        => await s.FindAsync(id, ct) is { } o ? TypedResults.Ok(o) : TypedResults.NotFound();

    static Task<Created<OrderDto>> Create(CreateOrder cmd, IOrderService s, CancellationToken ct) => s.CreateAsync(cmd, ct);
}

